{"description":"Find FPbase matches for our specific PDB proteins","cmd":"cd /tmp && python3 << 'EOF'
import json
data = json.load(open('/tmp/fp.json'))
# Build a lookup of all proteins by name and aliases
keywords = ['TagRFP675','PSmOrange','mCherry','TagRFP','HcRed','IFP2.0','Azami','Acropora','Olindias','Dendronephthya','Verrillofungia','Cnidopus','Chromo','Aequorea','Clover','d1Eos','mEos','Gamillus','pcDronpa','mGeos','mKikGR','moxNeonGreen','Padron','pcStar','mc2']
for kw in keywords:
    hits = []
    for p in data:
        name = p['name'].lower()
        aliases = [str(a).lower() for a in (p.get('aliases') or [])]
        if kw.lower() in name or kw.lower() in ' '.join(aliases):
            hits.append((p['name'], p['slug'], p.get('aliases'), p['states']))
    print(f"--- {kw} ---")
    for h in hits[:5]:
        print(h)
    if not hits:
        print("(none)")
EOF","yield_time_ms":30000}

{"description":"Parse FPbase CSV and map PDB IDs to FPbase entries","cmd":"cd /tmp && python3 << 'EOF'
import csv
pdb_ids = ['2IB5','4KGE','4Q7T','1KFD','5JZL','6AA7','3ADF','5WJ2','3M22','2H5Q','3MGF','5Y01','2VZX','4CQH','1YZW','2CHA','3KZY','1AK4','5P21','1H6R']
rows = list(csv.DictReader(open('fp_all.csv')))
print("rows:", len(rows))
# Each row has 'pdb', 'pdb.0'..'pdb.9'
hits = {}
for r in rows:
    pdb_fields = []
    for k,v in r.items():
        if k.startswith('pdb') and v:
            pdb_fields.append(v)
    # find which of our pdb_ids appear
    found = [pid for pid in pdb_ids if pid in pdb_fields or pid.lower() in [x.lower() for x in pdb_fields]]
    if found:
        hits.setdefault(tuple(found), []).append((r['name'], r['slug'], pdb_fields))
for k,v in hits.items():
    print(k, '->', v)
EOF","yield_time_ms":30000}

