{"description":"Extract canonical sequences from mmCIF","cmd":"cd /tmp && python3 << 'EOF'
import re
for name, path in [("5WJ2", "5wj2.cif"), ("2H5Q", "2h5q.cif")]:
    txt = open(path).read()
    # find the _entity_poly.pdbx_seq_one_letter_code_can section
    m = re.search(r'_entity_poly\.pdbx_seq_one_letter_code_can\s+(\d+)\s+(\d+)\s+.*?\n;(.*?)\n\s*#', txt, re.S)
    print(name, "canonical seq:")
    if m:
        print("code length:", m.group(2))
        print("".join(m.group(3).split()))
    else:
        # try alternate
        m2 = re.search(r'_entity_poly\.pdbx_seq_one_letter_code_can.*?\n;(.*?)\n\s*#', txt, re.S)
        if m2:
            print("".join(m2.group(1).split()))
EOF","yield_time_ms":30000}

